insert into public.products (id,category,badge,badge_ar,name,name_ar,description,description_ar,specs,specs_ar,datasheet_url,sort_order) values
('p1','management','Best Seller','الأكثر مبيعاً','Perforated Cable Trays','حوامل كابلات مثقبة','Manufactured from high-grade galvanized steel, engineered for efficient cable routing and proper ventilation.','مصنّعة من صلب مجلفن عالي الجودة لتمرير الكابلات بكفاءة مع تهوية مناسبة.','["Thickness: 1.0mm - 2.0mm","Hot-Dip Galvanized & Powder Coated","High load capacity"]'::jsonb,'["السمك: 1.0 - 2.0 مم","جلفنة على الساخن وطلاء بودرة","تحمّل أحمال عالية"]'::jsonb,null,0),
('p2','management','Industrial','صناعي','Heavy Duty Cable Ladders','سلالم كابلات ثقيلة','Robust structural side-rail design built for heavy power cabling in industrial plants and infrastructure.','تصميم بجوانب هيكلية قوية لكابلات القدرة الثقيلة في المصانع والبنية التحتية.','["Optimal strength for massive loads","NEMA & IEC compliant","Corrosion resistant"]'::jsonb,'["قوة مثالية للأحمال الكبيرة","مطابقة لمعايير NEMA و IEC","مقاومة للصدأ"]'::jsonb,null,1),
('p3','management','Telecom','اتصالات','Wire Mesh Cable Trays','حوامل كابلات شبكية','Lightweight and flexible wire mesh system designed specifically for telecommunications and data centers.','نظام شبكي خفيف ومرن مصمم لشبكات الاتصالات ومراكز البيانات.','["Easy on-site fabrication","Maximum airflow & ventilation","Zinc plated finish"]'::jsonb,'["سهل التشكيل في الموقع","تهوية وتدفق هواء أقصى","تشطيب مطلي بالزنك"]'::jsonb,null,2),
('p4','management','Accessory','ملحقات','Cable Tray Covers','أغطية حوامل الكابلات','Secure protective covers designed to shield cables from external environmental hazards and debris.','أغطية حماية تحمي الكابلات من العوامل الخارجية والأتربة.','["Peak, Flanged, and Solid types","Secure snap-on installation","Weatherproof protection"]'::jsonb,'["أنواع: مدببة، بحواف، وصلبة","تركيب بالضغط","حماية من العوامل الجوية"]'::jsonb,null,3),
('p5','management','Commercial','تجاري','Cable Trunking Systems','مجاري كابلات مغلقة','Enclosed sheet metal trunking systems for commercial wiring and indoor office cable routing.','مجاري معدنية مغلقة للتمديدات التجارية وتمرير الكابلات داخل المكاتب.','["Removable lid for easy access","Clean aesthetic appearance","Pre-punched knockouts"]'::jsonb,'["غطاء قابل للإزالة","مظهر نظيف","فتحات سابقة التجهيز"]'::jsonb,null,4),
('p6','building','Building','مباني','Expanded Plaster Mesh','شبك محارة مفرود','Expanded metal mesh engineered to reinforce plasterwork and prevent structural wall cracks.','شبك معدني مفرود لتقوية أعمال المحارة ومنع شروخ الحوائط.','["Treated corrosion-resistant steel","Superior cement adhesion","Standard gauge sizes"]'::jsonb,'["صلب معالج ضد الصدأ","التصاق ممتاز بالأسمنت","مقاسات قياسية"]'::jsonb,null,5),
('p7','building','Building','مباني','Corner Bead Profiles','زوايا محارة','Galvanized steel corner beads providing straight, impact-resistant external corners for wall plaster.','زوايا صلب مجلفن لأركان خارجية مستقيمة ومقاومة للصدمات.','["Precision straightness","Perforated wings for keying","Impact resistant"]'::jsonb,'["استقامة دقيقة","أجنحة مثقبة للتثبيت","مقاومة للصدمات"]'::jsonb,null,6),
('p8','building','Framing','هياكل','Drywall Studs & Tracks','قوائم ومجاري درايوال','Light gauge galvanized steel framing components used for partitions and suspended ceilings.','عناصر هيكلية من صلب مجلفن خفيف للقواطع والأسقف المعلقة.','["High tensile strength steel","Pre-punched service holes","Quick screw-fix installation"]'::jsonb,'["صلب عالي مقاومة الشد","فتحات خدمات جاهزة","تركيب سريع بالمسامير"]'::jsonb,null,7),
('p9','management','Support','دعم','Unistrut Channels (C-Channels)','قطاعات يونيستروت (C)','Versatile slotted or solid metal framing channels used for structural support and mechanical brackets.','قطاعات معدنية متعددة الاستخدامات، مخرّمة أو مصمتة، للدعم الإنشائي والحوامل الميكانيكية.','["Available in Single & Double","Standard depth: 41mm","Heavy gauge carbon steel"]'::jsonb,'["متوفرة مفردة ومزدوجة","العمق القياسي: 41 مم","صلب كربوني ثقيل"]'::jsonb,null,8),
('p10','management','Hardware','تثبيت','Cable Management Brackets','حوامل تثبيت الكابلات','Heavy-duty wall and ceiling brackets designed to securely support cable tray and ladder runs.','حوامل حائط وسقف ثقيلة لتثبيت مسارات الحوامل والسلالم.','["Cantilever & Trapeze brackets","High load rating support","Hot-dip galvanized coating"]'::jsonb,'["حوامل كابولي وترابيزي","تحمّل أحمال عالية","جلفنة على الساخن"]'::jsonb,null,9)
insert into public.accreditations (id,name,title_en,title_ar,desc_en,desc_ar,file_url,sort_order) values
('a1','ISO 9001:2015','Quality Management System','نظام إدارة الجودة العالمية','International quality control standard for steel manufacturing.','الاعتماد الدولي لإدارة ضبط واستدامة الجودة لمراحل التصنيع.',null,0),
('a2','ISO 14001:2015','Environmental Management','نظام الإدارة البيئية','Environmental safety compliance and sustainable steel mill protocols.','الالتزام التام بالتصنيع المستدام والحد من الانبعاثات الكربونية.',null,1),
('a3','ISO 45001:2018','Occupational Health & Safety','السلامة والصحة المهنية','World-class workplace safety and structural hazard control.','توفير أقصى درجات حماية العمالة وبيئة العمل الصناعية.',null,2),
('a4','ASTM A123 / A123M','Hot-Dip Galvanizing Standard','اعتماد جلفنة الصلب على الساخن','Zinc coating thickness and anti-corrosion specification.','مطابقة سمك طبقة الخارصين ومقاومة التآكل والصدأ.',null,3),
('a5','IEC 61537 Standard','Cable Tray Systems Compliance','شهادة حوامل وسلالم الكابلات','International standard for electrical cable tray and ladder systems.','مطابقة أنظمة مسارات الكابلات الكهربائية للأحمال والمواصفات الأوروبية.',null,4),
('a6','BS EN 10346','Continuously Hot-Dip Coated Steel','اعتماد الصفائح الفولاذية المغلفنة','Continuously hot-dip coated steel flat products certification.','اعتماد معايير الجودة للشرائح الفولاذية المستخدمة في التدلفين.',null,5),
('a7','ISO 50001:2018','Energy Management System','نظام إدارة الطاقة الصناعية','Industrial energy efficiency and optimized furnace management.','ترشيد كفاءة استهلاك الطاقة في أفرام الجلفنة وخطوط الإنتاج.',null,6),
('a8','CE Marking Certificate','European Conformity Certification','شهادة التوافق الأوروبي CE','European market conformity for structural steel products.','اعتماد التصدير لأسواق الاتحاد الأوروبي والشرق الأوسط.',null,7),
('a9','RoHS Compliance','Restriction of Hazardous Substances','شهادة خلو المنتجات من المواد الخطرة','Environmentally clean and non-hazardous metal finishing.','مطابقة منتجات حوامل الكابلات للمعايير البيئية النظيفة.',null,8),
('a10','ISO/IEC 17025','Testing Laboratory Accreditation','اعتماد مختبرات الفحص والقياس','Accreditation of in-house tensile and thickness testing labs.','اعتماد دقة اختبارات شد الصلب واختبارات الجودة الداخلية.',null,9)
